"""Cross-language wire-format proof: this fixture was generated by the
MOBILE (Dart) client -- packed, Ed25519-signed, and XChaCha20-Poly1305
encrypted using `mobile/lib/core/crypto/` -- and is decoded here using only
the real backend modules (mesh_crypto, wire_format, signatures).

This is not a Python reimplementation testing itself: it is proof that two
independent implementations, in two different languages, agree byte for
byte on the wire contract. If either side's struct layout, byte order, or
crypto construction ever drifts, this fixture stops decoding and this test
fails -- which is exactly the failure mode a same-language test suite
cannot catch.

Regenerate the fixture with (from mobile/):
    dart run tool/generate_interop_fixture.dart
"""

from __future__ import annotations

import base64

import pytest

from app.mesh import wire_format
from app.security import mesh_crypto, signatures

# --- Fixture, generated by the Dart client -----------------------------------

DEVICE_PUBLIC_KEY_B64 = "tI8IObVy8rjoY+9fkWSszow14nPtMol7dvNTjep6r+k="
SECTOR_KEY_B64 = "CH+JJlsOQ74SSKbboXuWFBsCpot6Z1lfDcrxvIT+ezI="
BLOB_B64 = (
    "7C6/RTfvJQPfxO35/MoZM3XDbcx9BQWGMEFWwH1MjZeBKp/JA1niNVffQ5NMp2RwOXSoDsMkmgy"
    "KZtrqhWs20++kCeq0tk2Sp2ow3Tn1a6KTy/AxZVsjr04epR7DCnl3YciMyKcaFl5phWpg4kZPfJ"
    "16HYUm7l/ZT/JX9oHCvFkHdTI="
)

# accuracy_m=6.5 is a clean decimeter value (65 exactly) and speed_mps=1.35
# similarly clean at the centimeter scale -- neither sits on a rounding tie,
# unlike an earlier draft of this fixture (12.25m, which is an exact
# half-decimeter tie and round-trips to 12.2 under Python's round-half-even,
# not a wire-format bug, just a bad choice of fixture value).
EXPECTED_WIRE_ID = 424242
EXPECTED_RECORDED_AT_MS = 1780000000123
EXPECTED_LAT = 31.771959
EXPECTED_LNG = 35.217018
EXPECTED_ACCURACY_M = 6.5
EXPECTED_SPEED_MPS = 1.35
EXPECTED_BATTERY_PCT = 73
EXPECTED_IS_MOCKED = False


@pytest.fixture(scope="module")
def decoded_payload() -> tuple[wire_format.PointPayload, bytes, bytes]:
    """Decrypts the Dart-generated blob and verifies its Ed25519 signature,
    using nothing but the real backend modules. Runs once per test module."""
    sector_key = base64.b64decode(SECTOR_KEY_B64)
    device_public_key = base64.b64decode(DEVICE_PUBLIC_KEY_B64)
    blob = base64.b64decode(BLOB_B64)

    bundle = mesh_crypto.decrypt(sector_key, blob)
    payload_bytes = bundle[: wire_format.PAYLOAD_BYTES]
    signature = bundle[wire_format.PAYLOAD_BYTES :]

    assert len(signature) == signatures.ED25519_SIGNATURE_BYTES
    assert signatures.verify(device_public_key, payload_bytes, signature)

    return wire_format.unpack(payload_bytes), payload_bytes, signature


def test_blob_decrypts_with_the_dart_generated_sector_key(decoded_payload) -> None:
    # decoded_payload fixture already decrypted successfully; this test
    # exists so a decrypt failure reports here with a clear name rather than
    # as a fixture-setup error.
    assert decoded_payload is not None


def test_signature_verifies_against_the_dart_generated_public_key(
    decoded_payload,
) -> None:
    _, payload_bytes, signature = decoded_payload
    device_public_key = base64.b64decode(DEVICE_PUBLIC_KEY_B64)
    assert signatures.verify(device_public_key, payload_bytes, signature)


def test_wire_id_matches(decoded_payload) -> None:
    payload, _, _ = decoded_payload
    assert payload.wire_id == EXPECTED_WIRE_ID


def test_recorded_at_ms_matches(decoded_payload) -> None:
    payload, _, _ = decoded_payload
    assert payload.recorded_at_ms == EXPECTED_RECORDED_AT_MS


def test_lat_lng_match_within_fixed_point_precision(decoded_payload) -> None:
    payload, _, _ = decoded_payload
    assert payload.lat == pytest.approx(EXPECTED_LAT, abs=1e-6)
    assert payload.lng == pytest.approx(EXPECTED_LNG, abs=1e-6)


def test_accuracy_and_speed_match_within_fixed_point_precision(
    decoded_payload,
) -> None:
    payload, _, _ = decoded_payload
    assert payload.accuracy_m == pytest.approx(EXPECTED_ACCURACY_M, abs=0.05)
    assert payload.speed_mps == pytest.approx(EXPECTED_SPEED_MPS, abs=0.005)


def test_battery_and_mocked_flag_match(decoded_payload) -> None:
    payload, _, _ = decoded_payload
    assert payload.battery_pct == EXPECTED_BATTERY_PCT
    assert payload.is_mocked == EXPECTED_IS_MOCKED


def test_forged_signature_over_the_same_payload_is_rejected(decoded_payload) -> None:
    """A tamper check crossing the language boundary: flipping a bit in the
    Dart-produced signature must still be rejected by the Python verifier."""
    _, payload_bytes, signature = decoded_payload
    device_public_key = base64.b64decode(DEVICE_PUBLIC_KEY_B64)

    tampered = bytearray(signature)
    tampered[-1] ^= 0xFF
    assert not signatures.verify(device_public_key, payload_bytes, bytes(tampered))


def test_wrong_sector_key_fails_to_decrypt_the_dart_blob() -> None:
    blob = base64.b64decode(BLOB_B64)
    wrong_key = b"\x00" * 32
    with pytest.raises(mesh_crypto.MeshCryptoError):
        mesh_crypto.decrypt(wrong_key, blob)
